import{a as s,b as e,c as n}from"./summer2-OyMWjXo_.js";import{W as t,P as i}from"./prepa1-BtaRFhdk.js";import{A as o}from"./about-CGKZoOT2.js";const r="/assets/weekend_school-Bw5ldeqT.jpeg",a="/assets/hero10-aGXckqlR.jpeg",l="/assets/summer5-Dl7vwfb2.jpeg",c="/assets/prepa-CBdvNGbW.jpeg",d="/assets/prepa3-DT9KQUmd.jpeg",u="/assets/global-rgY6cybZ.png",m="/assets/stem3-EBhi5_Vk.jpeg",p="/assets/summer3-DNwlWXRD.jpg",g="/assets/global-s%20(1)-DyySCCfi.jpg",h="/assets/global-s%20(2)-BfI3PyI1.jpg",y="/assets/global-s%20(3)-DjDYK-Az.jpg",w=[{slug:"stem",title:"STEM National Project",summary:"A country‑wide contest that rewards clear thinking over memorization. Students tackle authentic, multi‑step STEM problems—testing ideas, defending methods, and connecting classroom theory to real‑world impact.",images:[s,e,t,m],features:["Drive for problem solving critical thinking and innovation.","Multi‑disciplinary problems (Math, Physics, Chemistry, Biology)","Emphasis on reasoning, method, and communication","Cerificates of participation to all participant","Mentor clinics and exam‑prep sessions built into the calendar","Cash Prizes, Awards, recognition, for top studens"],details:["Eligibility: Form 4 – Upper Sixth (O/L & A/L)","Format: Every December","Outcomes: Deeper STEM literacy, critical thinking, and real‑world problem‑solving"],sections:[{title:"About the National STEM Olympiad",body:"The Knowledge Center National STEM Olympiad is the nation’s most ambitious science education program, built to foster deep conceptual understanding, independent thinking, and creative problem-solving among young learners. It moves students beyond formulaic learning into scientific reasoning, experimentation, and real-world application. At the heart of the initiative is a structured system of challenges that push students to think critically, design solutions, and demonstrate mastery rather than memorize content. The program has consistently produced high-performing students who excel in national competitions and advanced academic pathways. The initiative culminates in the National STEM Convention, an annual, impact-heavy gathering that celebrates excellence and innovation in science education. All STEM laureates are transported on a fully funded trip to the host region, where they participate in a two-day convention designed around learning, recognition, and exposure. The convention brings together top educators, national dignitaries, KC scholars, alumni, and the country’s brightest students. It concludes with a national conference that connects talent, leadership, and opportunity—marking both a celebration and a launchpad for future innovators."}]},{slug:"summer-education",title:"Summer Education Program",summary:"Intensive summer sessions designed to help students get access to quality education, that inspires a nexus for change makers in society and grow practical skills during school breaks.",images:[n,l,e,a,p],features:["2‑month intensive learning blocks (July–August)","Interactive audio‑visual lectures from passionate educators","Mentorship, orientation, and study planning","Leadership masterclass and creative writing","Tech Boot Camp (Python and AI)","Clubs Activities: Music, Engineering, Creative writing","Sports, recreation, and wellness days","Global Scholars prep: essays, SATs, scholarships"],details:["Duration: 2 months (July–August)","Format: Modern classrooms with audio-visual lectures","Extras: Additional T-shirts for all registered students","Outcomes: Academic excellence, Skill acquistion, global stage scholars"],sections:[{title:"About the Summer Education Program",body:"The KC Summer Education Program is a two-month, high-intensity learning experience designed to re-ignite curiosity and rebuild mastery in secondary school students. It reimagines what African education can be by replacing rote memorization with applied learning, experimentation, and creative exploration. Through hands-on STEM innovation projects, AI-assisted personalized learning, public speaking, creative writing, and immersive audio-visual lessons powered by simulations, students develop the critical competencies required for today’s globally connected economy. Learners do not just study concepts—they build, test, speak, write, and solve. The program directly responds to the failures of traditional schooling systems that reward recall over understanding and grades over growth. By creating a vibrant, experiential learning environment each summer, KC enables students to fall back in love with learning while acquiring real-world skills in problem-solving, collaboration, communication, and innovation."}]},{slug:"weekend-school",title:"KC Weekend School",summary:"Flexible weekend classes for reinforcement, acceleration, and exam mastery with personalized coaching.",images:[r,t,o,a],features:["Saturday and Sunday options that fit school schedules","Audio‑visual lectures from passionate tutors","Supplementary materials and practice drills","Peer tutoring and collaborative learning","Progress tracking and regular assessments","Mock tests with feedback and improvement plans"],details:["When: Sat–Sun blocks","Focus: Reinforcement, revision, and mock tests","Support: 1:1 feedback and tailored study plans","Outcomes: Consistent weekly progress and exam readiness"],sections:[{title:"About the Weekend School",body:"The KC Weekend School is a research-driven remedial education program designed to rebuild academic foundations, close chronic learning gaps, and restore confidence in students. It delivers structured, individualized instruction through small-group learning, continuous assessment, and multi-sensory teaching methods. The program directly addresses the widespread lack of conceptual mastery in science subjects by replacing fragmented private tutoring with a coherent, accountable system. Students are guided to not only meet curriculum standards but exceed them—developing the ability."}]},{slug:"global-scholars-program",title:"Global Scholars Program",summary:"We prepare scholars for opportunities beyond borders—competitive scholarships, exchange programs, and global leadership.",images:[u,g,h,y],features:["Mentorship from seasoned staff and alumni","Application strategy for global opportunities","Career orientation and leadership projects","Training on essays, statements, and interviews","SAT/ACT/TOEFL prep and timelines","Progress tracking across milestones"],details:["When: Year‑round with intensive programs","Focus: Essays, testing, recommendations, portfolios","Support: 1:1 mentorship and peer reviews","Outcomes: Competitive applications and global placement"],sections:[{title:"About the Global Scholars Program",body:"The KC Global Scholars Program connects Africa’s highest-potential students to world-class international education opportunities. Through SAT preparation, registration support, and personalized study-abroad consulting, the program levels the international playing field for students who would otherwise lack access, guidance, or exposure. The program is built on a fully integrated support system that helps students prepare, apply, and succeed globally. KC scholars have gone on to attend leading institutions across the United States, Europe, and Africa, including Ivy League universities and top global campuses. Rooted in the belief that talent is evenly distributed but opportunity is not, the Global Scholars Program transforms academic ambition into measurable outcomes. It has established a strong alumni mentorship ecosystem, partnerships with leading secondary schools, and a proven record of significant standardized test score improvements—positioning KC as a trusted bridge between African talent and global opportunity."}]},{slug:"kc-prepa",title:"KC Prepa",summary:"Focused preparation for competitive entrance exams with elite mentoring and proven results.",images:[c,d,i],features:["Audio‑visual lectures from expert tutors","Distinguished scholarly community across the nation","Exceptional success rates with alumni","Career orientation","Career‑defining experiences and field seminars","Tracks: Engineering, Medicine, Agriculture, ICT","Progress tracking and targeted assessments"],details:["When: Summer before entrance exams","Focus: Concept mastery, revision, and timed mocks","Support: 1:1 feedback and adaptive study plans","Outcomes: Competitive scores and university readiness"]}];export{w as p};
